def send_post_request(url, path, data, header):
    connec = http.client.HTTPConnection(url)#建立连接
    connec.request('POST', path, data, header)
    result = connec.getresponse()
    print(result.status, result.reason)

    data1 = result.read()
    print(data1)  #
    connec.close()
    



